import { Logger } from "trm-commons";
import { SystemConnector } from "../../../systemConnector";

/**
 * Temporary transports created by an action that may be taken out of the connected system's import queue:
 * - `prepared`: dummy transport receiving a release payload (upgrade dummy)
 * - `deletion`: dummy transport receiving a deletion payload
 * - `rollback-deletion`: deletion transport generated by a rollback
 *
 * Backup (BKP) transports are deliberately not a kind: they stay in the queue, re-imported on rollback
 * and kept for manual recovery.
 */
export type DequeueableTransportKind = 'prepared' | 'deletion' | 'rollback-deletion';

const backupTransports = new Set<string>();

function key(trkorr: string): string {
    return trkorr.trim().toUpperCase();
}

/** Marks a transport as a backup: no cleanup can ever take it out of the import queue. */
export function protectBackupTransport(trkorr: string): void {
    backupTransports.add(key(trkorr));
}

export function isBackupTransport(trkorr: string): boolean {
    return backupTransports.has(key(trkorr));
}

/**
 * Takes a temporary transport out of the connected system's import queue. Only the connected system's
 * queue can be changed (another system's queue needs its credentials). Backup transports are refused.
 */
export async function dequeueTransport(trkorr: string, kind: DequeueableTransportKind): Promise<void> {
    if (isBackupTransport(trkorr)) {
        throw new Error(`Transport ${trkorr} is a backup: it must stay in the ${SystemConnector.getDest()} import queue.`);
    }
    Logger.loading(`Removing ${kind} transport ${trkorr} from ${SystemConnector.getDest()} import queue...`, true);
    await SystemConnector.deleteTmsTransport(trkorr, SystemConnector.getDest());
}

/**
 * Takes every transport out of the connected system's import queue, attempting all of them:
 * the first failure is thrown after the pass.
 */
export async function dequeueTransports(transports: Array<{ trkorr: string, kind: DequeueableTransportKind }>): Promise<void> {
    let firstError: unknown;
    for (const transport of transports) {
        try {
            await dequeueTransport(transport.trkorr, transport.kind);
        } catch (error) {
            Logger.warning(`Couldn't remove transport ${transport.trkorr} from ${SystemConnector.getDest()} import queue: ${error instanceof Error ? error.message : String(error)}`, { important: true });
            firstError ||= error;
        }
    }
    if (firstError) {
        throw firstError;
    }
}
